# Generated by manage.py generate_test_cases.
"""Verify physical moves preserve file identity, bytes, and all references."""

from django.core.files.uploadedfile import SimpleUploadedFile

from bloomerp.models import FileNode, FileReference
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestMoveFileComponent(BloomerpComponentTestCase):
    """Exercise physical destination selection and authorization."""

    view_name = "components_files_move"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Move shared content without changing its logical attachment locations."""
        folder = FileNode.objects.create(name="Physical", kind="FOLDER")
        file = FileNode.objects.create(
            name="source.txt",
            kind="FILE",
            content=SimpleUploadedFile("source.txt", b"bytes"),
        )
        reference = FileReference.objects.create(
            file=file, content_object=self.CustomerModel.objects.first()
        )
        return [
            RequestScenario(
                name="Move shared file into physical folder",
                method="POST",
                user=self.admin_user,
                view_kwargs={"file_id": file.pk},
                data={"target_folder": folder.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        FileNode.objects.filter(
                            pk=file.pk, parent=folder, content=file.content.name
                        ).exists()
                        and FileReference.objects.filter(
                            pk=reference.pk, file=file
                        ).exists()
                    )
                ),
            ),
            RequestScenario(
                name="Deny unauthorized physical move",
                method="POST",
                user=self.normal_user,
                view_kwargs={"file_id": file.pk},
                data={"target_folder": folder.pk},
                expected=ExpectedResult(
                    status_code=403,
                    response_validators=lambda response: FileNode.objects.filter(
                        pk=file.pk, parent=None
                    ).exists(),
                ),
            ),
        ]
